insert into public.football_team_profiles (team_id, nickname, tags, intro) values
(678, null, '{암스테르담,요한 크루이프 아레나,1900년 창단}', $t$<p>아약스는 네덜란드 수도 암스테르담을 연고로 하는 네덜란드 최다 리그 우승 구단입니다. 요한 크루이프를 앞세워 1971년부터 1973년까지 유러피언컵 3연패를 달성했고, 1995년에는 젊은 선수들로 챔피언스리그 정상에 다시 올랐습니다. 유소년 아카데미는 세계 최고 수준으로 꼽히며, 홈구장 이름도 크루이프를 기려 요한 크루이프 아레나로 바뀌었습니다. 페예노르트와 맞붙는 "더 클라시커"는 네덜란드 최대의 라이벌전입니다.</p><p>토리코리 관전 포인트: 아약스는 홈에서 경기를 주도하는 팀이라 홈 경기당 승점이 시즌 성적을 좌우하는 경우가 많습니다. 최근 5경기 흐름과 함께 전반 득점 비율을 보면 경기 초반부터 몰아붙이는 경기가 얼마나 되는지 알 수 있습니다.</p>$t$),
(674, '부런', '{에인트호번,필립스 스타디온,1913년 창단}', $t$<p>PSV 에인트호번은 전자기업 필립스의 직원 스포츠 클럽으로 출발한 구단으로, 이름의 PSV도 "필립스 스포츠 연합"이라는 뜻입니다. 1978년 UEFA컵, 1988년 유러피언컵을 들어 올렸고 호나우두와 판 니스텔로이 같은 스타가 거쳐 갔습니다. 거스 히딩크 감독과 함께 박지성과 이영표가 뛰며 2005년 챔피언스리그 4강에 올라 한국 팬들에게 특히 친숙한 구단입니다.</p><p>토리코리 관전 포인트: PSV는 리그에서 득점력이 높은 시즌이 많아 2.5골 오버 비율을 먼저 확인해 보는 것이 좋습니다. 원정 경기당 승점이 홈과 비슷하게 유지되는 시즌이 우승 경쟁에서 앞서 나간 시즌이었습니다.</p>$t$),
(675, null, '{로테르담,더 카위프,1908년 창단}', $t$<p>페예노르트는 항구 도시 로테르담 남부를 연고로 하는 구단으로, 1970년 네덜란드 구단 최초로 유러피언컵을 차지했고 같은 해 인터콘티넨털컵까지 들어 올렸습니다. 1974년과 2002년에는 UEFA컵 정상에 올랐으며, 홈구장 더 카위프는 뜨거운 응원으로 유명합니다. 2002년부터 송종국이 뛰었고, 2024년에는 황인범이 합류해 한국 팬들의 관심을 받았습니다. 아약스와의 "더 클라시커"는 네덜란드 최대의 라이벌전입니다.</p><p>토리코리 관전 포인트: 더 카위프의 분위기 덕분에 페예노르트는 홈과 원정 성적 차이가 뚜렷하게 나타나는 편이라 홈·원정 경기당 승점을 나눠 보는 것이 좋습니다. 후반 득점 비율이 높은 시즌에는 경기 막판까지 결과를 단정하기 어렵습니다.</p>$t$),
(682, '카스코펀', '{알크마르,AFAS 스타디온,1967년 창단}', $t$<p>AZ 알크마르는 1967년 알크마르 54와 FC 잔스트레이크가 합쳐 만들어진 구단으로, 치즈 시장으로 유명한 도시답게 "카스코펀(치즈 머리)"이라는 별명을 갖고 있습니다. 1981년과 2009년 리그 정상에 올랐고, 1981년에는 UEFA컵 결승까지 진출했습니다. 유소년 육성에 강해 2023년 UEFA 유스리그에서 우승했으며, KNVB컵도 여러 차례 차지했습니다.</p><p>토리코리 관전 포인트: AZ는 상위권 팀 가운데 실점 관리가 안정적인 시즌이 많아 무실점 비율이 좋은 판단 기준이 됩니다. 최근 5경기 결과가 들쭉날쭉할 때는 유럽 대회 일정이 겹친 시기인지 함께 확인해 보세요.</p>$t$),
(666, '투커르스', '{엔스헤데,더 흐롤스 베스터,1965년 창단}', $t$<p>FC 트벤테는 네덜란드 동부 엔스헤데를 연고로 하며, 1965년 스포르트클뤼프 엔스헤데와 엔스헤데스 보이스가 합쳐 탄생했습니다. 1975년 UEFA컵 결승에 올랐고, 2009-10 시즌에는 스티브 매클래런 감독 아래 구단 역사상 첫 리그 우승을 차지했습니다. 별명 "투커르스"는 이 지역 트벤테 사람들을 부르는 말에서 왔으며, 홈구장 더 흐롤스 베스터는 열성적인 관중으로 알려져 있습니다.</p><p>토리코리 관전 포인트: 트벤테는 홈에서 강한 모습을 자주 보여 홈 경기당 승점을 원정과 비교해 보면 팀의 성격이 잘 드러납니다. 양팀 득점 비율이 낮은 시즌에는 한 골 차 승부가 많아집니다.</p>$t$),
(676, null, '{위트레흐트,스타디온 갈헨바르트,1970년 창단}', $t$<p>FC 위트레흐트는 1970년 지역의 세 구단이 합쳐 만들어진 구단으로, 네덜란드 중부 위트레흐트를 연고로 합니다. 1985년, 2003년, 2004년 KNVB컵을 들어 올렸으며 리그에서는 꾸준히 중상위권을 노리는 팀입니다. 홈구장 스타디온 갈헨바르트는 관중석이 경기장과 가까워 분위기가 뜨겁고, 아약스와의 경기는 팬들 사이에서 특히 거친 라이벌전으로 꼽힙니다.</p><p>토리코리 관전 포인트: 위트레흐트는 갈헨바르트에서의 성적이 시즌 순위를 크게 좌우하므로 홈 경기당 승점을 먼저 살펴보세요. 전반 실점이 많은 시기에는 경기 운영이 어려워지는 경향이 있어 전반·후반 실점을 나눠 보는 것이 좋습니다.</p>$t$),
(673, null, '{헤이렌베인,아버 렌스트라 스타디온,1920년 창단}', $t$<p>SC 헤이렌베인은 네덜란드 북부 프리슬란트 지방을 대표하는 구단으로, 프리슬란트 깃발의 수련잎 문양을 유니폼에 담고 있습니다. 홈구장 이름은 구단의 전설적인 공격수 아버 렌스트라에서 따왔습니다. 판 니스텔로이와 훈텔라르가 이곳을 거쳐 빅클럽으로 성장했고, 2009년에는 KNVB컵을 차지했습니다. 흐로닝언과의 경기는 "북부 더비"로 불립니다.</p><p>토리코리 관전 포인트: 헤이렌베인은 홈과 원정 성적 차이가 큰 시즌이 많아 홈·원정 경기당 승점을 나눠 보는 것이 유용합니다. 2.5골 오버 비율이 높은 시즌에는 득점과 실점이 함께 많은 경기가 자주 나옵니다.</p>$t$),
(677, null, '{흐로닝언,에우로보르흐,1971년 창단}', $t$<p>FC 흐로닝언은 지역 구단 GVAV의 프로 부문을 이어받아 1971년 새로 출범한 구단으로, 네덜란드 북부 최대 도시 흐로닝언을 연고로 합니다. 아르연 로번이 이 구단 유소년 출신이며, 루이스 수아레스도 유럽 커리어를 이곳에서 시작했습니다. 2015년 KNVB컵에서 우승하며 구단 역사상 첫 주요 트로피를 들어 올렸고, 헤이렌베인과의 "북부 더비"는 지역 최대의 경기입니다.</p><p>토리코리 관전 포인트: 흐로닝언은 에우로보르흐의 열기 덕분에 홈 경기당 승점이 원정보다 뚜렷하게 높은 시즌이 많습니다. 최근 5경기와 무실점 비율을 함께 보면 수비가 안정된 시기인지 쉽게 판단할 수 있습니다.</p>$t$),
(6806, null, '{로테르담,헷 카스테일,1888년 창단}', $t$<p>스파르타 로테르담은 1888년 창단된 네덜란드에서 가장 오래된 프로 축구 구단입니다. 1959년까지 여섯 차례 네덜란드 챔피언에 올랐고, KNVB컵도 세 번 차지했습니다. 홈구장은 성 모양의 외관 덕분에 "헷 카스테일(성)"이라 불리며, 빨간색과 흰색 세로 줄무늬 유니폼은 잉글랜드 선덜랜드에서 영감을 받은 것으로 알려져 있습니다. 같은 도시의 페예노르트, 엑셀시오르와 로테르담 더비를 치릅니다.</p><p>토리코리 관전 포인트: 스파르타는 강팀을 상대로 끈질기게 버티는 경기가 많아 양팀 득점 비율과 무실점 비율을 함께 보면 경기 성향이 잘 보입니다. 후반 실점이 늘어나는 시기에는 막판 집중력이 순위 싸움의 변수가 됩니다.</p>$t$),
(670, null, '{로테르담,스타디온 바우데스테인,1902년 창단}', $t$<p>엑셀시오르는 로테르담 동부 크랄링언 지역을 연고로 하는 구단으로, 페예노르트와 스파르타에 이어 로테르담의 세 번째 프로 구단입니다. 오랫동안 페예노르트와 협력 관계를 맺고 젊은 선수들을 임대로 받아 키워 왔습니다. 1부와 2부를 자주 오르내렸지만 작은 예산으로 1부 잔류를 이뤄내는 저력을 보여 왔고, 아담한 홈구장 스타디온 바우데스테인은 가족적인 분위기로 알려져 있습니다.</p><p>토리코리 관전 포인트: 엑셀시오르는 경기당 실점이 많은 시즌이 잦아 2.5골 오버 비율이 높게 나오는 편입니다. 홈 경기당 승점이 잔류 경쟁의 핵심이니 최근 5경기 홈 결과를 눈여겨보세요.</p>$t$),
(1915, null, '{네이메헌,더 호페르트,1900년 창단}', $t$<p>NEC 네이메헌은 네덜란드에서 가장 오래된 도시로 꼽히는 네이메헌을 연고로 하는 구단입니다. 홈구장 더 호페르트는 숲이 우거진 공원 안에 자리하고 있습니다. KNVB컵 결승에 여러 차례 올랐지만 아직 우승 트로피는 없으며, 2024년 결승에서도 페예노르트에 아쉽게 패했습니다. 인근 아른험의 피테서와 치르는 "헬데르란트 더비"가 대표적인 라이벌전입니다.</p><p>토리코리 관전 포인트: NEC는 중위권에서 승점을 차곡차곡 쌓는 팀이라 경기당 승점과 무승부 흐름을 함께 보는 것이 좋습니다. 전반·후반 득점을 나눠 보면 경기 후반에 강한 팀인지 확인할 수 있습니다.</p>$t$),
(684, '블라우빙어르스', '{즈볼레,MAC3PARK 스타디온,1910년 창단}', $t$<p>PEC 즈볼레는 네덜란드 동북부 오버레이설주의 주도 즈볼레를 연고로 하는 구단입니다. 별명 "블라우빙어르스(파란 손가락)"는 즈볼레 시민을 부르는 옛 별칭에서 왔습니다. 1990년대와 2000년대에는 FC 즈볼레라는 이름을 쓰기도 했으며, 2014년 KNVB컵 결승에서 아약스를 5-1로 꺾고 구단 첫 주요 트로피를 차지한 경기는 지금도 회자됩니다. 파란색과 흰색 유니폼을 입습니다.</p><p>토리코리 관전 포인트: 즈볼레는 홈 경기당 승점과 원정 경기당 승점의 차이를 비교해 볼 만합니다. 양팀 득점 비율이 높은 시즌이 많아 실점 관리가 잔류의 관건입니다.</p>$t$),
(718, null, '{데벤터르,더 아덜라르스호르스트,1902년 창단}', $t$<p>고 어헤드 이글스는 네덜란드 동부의 오래된 한자 도시 데벤터르를 연고로 하는 구단입니다. 영어식 이름 "고 어헤드"는 창단 초기 영국 축구의 영향을 받아 붙여졌습니다. 1917년부터 1933년까지 네 차례 네덜란드 챔피언에 올랐고, 홈구장 더 아덜라르스호르스트는 작지만 관중석이 경기장에 바짝 붙어 있어 뜨거운 분위기로 유명합니다. 오랜 역사에 비해 1부와 2부를 오간 시기가 길었지만, 지역 팬들의 충성도는 리그에서도 손꼽힙니다.</p><p>토리코리 관전 포인트: 고 어헤드 이글스는 홈에서 승점을 많이 따내는 팀이라 홈 경기당 승점이 순위를 가늠하는 좋은 지표입니다. 전반 득점이 나온 경기와 그렇지 않은 경기의 결과 차이도 함께 살펴보세요.</p>$t$),
(672, '트리콜로레스', '{틸뷔르흐,코닝 빌럼 II 스타디온,1896년 창단}', $t$<p>빌럼 II는 남부 도시 틸뷔르흐를 연고로 하며, 이 도시와 인연이 깊은 국왕 빌럼 2세의 이름을 따왔습니다. 빨강, 하양, 파랑의 삼색 유니폼에서 "트리콜로레스"라는 별명이 나왔습니다. 1916년, 1952년, 1955년 리그 정상에 올랐고 KNVB컵도 두 차례 들어 올렸으며, 1999-2000 시즌에는 챔피언스리그 본선 무대를 밟았습니다. 야프 스탐도 이 구단을 거쳐 성장했습니다.</p><p>토리코리 관전 포인트: 빌럼 II는 1부와 2부를 오가는 시기가 있었던 만큼 경기당 승점과 최근 5경기 흐름을 함께 보며 팀의 기세를 판단하는 것이 좋습니다. 무실점 비율이 높은 시즌에는 잔류 경쟁에서 한결 여유를 가졌습니다.</p>$t$),
(1920, null, '{시타르트,포르튀나 시타르트 스타디온,1968년 창단}', $t$<p>포르튀나 시타르트는 1968년 포르튀나 54와 시타르디아가 합쳐 만들어진 구단으로, 네덜란드 최남단 림뷔르흐주의 시타르트를 연고로 합니다. 독일, 벨기에 국경과 가까운 지역 특성상 다양한 국적의 선수가 뛰는 경우가 많습니다. KNVB컵 결승에 두 차례 올랐으며, 마르크 판 보멀이 이 구단 유소년 출신으로 프로 생활을 시작했습니다.</p><p>토리코리 관전 포인트: 포르튀나 시타르트는 원정 경기당 승점이 낮은 시즌이 많아 홈과 원정 성적을 나눠 보는 것이 중요합니다. 후반 실점이 많은 시기에는 리드를 지키지 못하는 경기가 늘어나니 전반·후반 실점을 확인해 보세요.</p>$t$),
(680, '오이바르스', '{덴하흐,빙골 스타디온,1905년 창단}', $t$<p>ADO 덴하흐는 네덜란드 정부와 국제사법재판소가 자리한 도시 덴하흐(헤이그)를 연고로 하는 구단입니다. 별명 "오이바르스(황새)"는 도시 문장에 그려진 황새에서 왔습니다. 1940년대에 두 차례 네덜란드 챔피언에 올랐고, 1968년과 1975년에는 KNVB컵을 차지했습니다. 노란색과 초록색 유니폼이 상징이며, 열정적인 홈 팬들로 잘 알려져 있습니다.</p><p>토리코리 관전 포인트: ADO 덴하흐는 홈 팬들의 응원을 등에 업고 홈 경기당 승점을 높게 쌓는 것이 시즌 운영의 기본입니다. 2.5골 오버 비율과 양팀 득점 비율을 함께 보면 이 팀의 경기가 어떤 흐름으로 흘러가는지 짐작할 수 있습니다.</p>$t$),
(1909, null, '{레이우아르던,캄뷔르 스타디온,1964년 창단}', $t$<p>캄뷔르는 프리슬란트주의 주도 레이우아르던을 연고로 하는 구단으로, 1964년 프로 구단으로 출범했습니다. 노란색과 파란색 유니폼을 입으며, 같은 프리슬란트 지역의 헤이렌베인과 치르는 "프리슬란트 더비"는 지역 팬들이 가장 기다리는 경기입니다. 1부와 2부를 여러 차례 오르내렸지만 열성적인 지역 팬들의 지지를 받는 구단입니다. 팀 이름은 연고 지역의 옛 지명에서 따왔습니다.</p><p>토리코리 관전 포인트: 캄뷔르는 홈 경기당 승점이 원정보다 높게 나타나는 경우가 많아 홈·원정 성적을 나눠 보는 것이 좋습니다. 경기당 실점과 무실점 비율이 잔류 경쟁의 흐름을 가장 잘 보여 주는 지표입니다.</p>$t$),
(1912, '비터 레이우언', '{벨선,BUKO 스타디온,1963년 창단}', $t$<p>텔스타르는 북홀란트주 벨선을 연고로 하는 구단으로, 1963년 지역 구단들이 힘을 합쳐 프로 구단으로 출범했습니다. 구단 이름은 1962년 발사된 통신위성 텔스타에서 따왔고, 별명 "비터 레이우언(하얀 사자)"은 흰색 유니폼에서 비롯됐습니다. 1970년대 후반 이후 오랫동안 2부 리그에 머물렀지만, 바닷가 공업 도시의 작은 구단으로 꾸준한 지역 팬층을 지켜 왔습니다.</p><p>토리코리 관전 포인트: 텔스타르처럼 2부 생활이 길었던 팀은 1부 상대와의 경기당 승점과 최근 5경기 흐름으로 적응 정도를 판단하는 것이 좋습니다. 전반 실점이 적은 경기에서 승점을 챙기는 경우가 많으니 전반·후반 실점을 함께 보세요.</p>$t$)
